	}
}

#FlagBoolean: {
	type: "BOOLEAN_FLAG_TYPE"
	rollouts: [...{
		description?: string
		#Rollout
	}]
}

#Variant: {
	key:          string & =~"^.+$"
	name:         string & =~"^.+$"
	description?: string
	attachment:   {...} | *null
}

#RuleSegment: {
	keys: [...string]
