	yamlv3 \"gopkg.in/yaml.v3\"
)

var (
	//go:embed flipt.cue
	cueFile []byte
	ErrValidationFailed = errors.New(\"validation failed\")
)

type Location struct {
	File string "'`json:"file,omitempty"`
	Line int `json:"line"`
	Column int `json:"column"`
}

type Error struct {
	Message string `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

type Result struct {
	Errors []Error `json:"errors"`
}

type validationErrors struct { errors []error }
func (e validationErrors) Error() string { return ErrValidationFailed.Error() }
func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }
func (e validationErrors) Unwrap() []error { return e.errors }

// Unwrap returns the individual errors in a multi-error validation result.
func Unwrap(err error) ([]error, bool) {
	var multi interface { Unwrap() []error }
	if errors.As(err, &multi) { return multi.Unwrap(), true }
	return nil, false
}

type FeaturesValidator struct {
	cue *cue.Context
	v cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil { return nil, v.Err() }
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks the YAML schema and all references within a feature file.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil { return err }
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil { return err }

	var issues []error
	for _, e := range cueerrors.Errors(v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))) {
		issue := Error{Message: e.Error(), Location: Location{File: file}}
		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			issue.Location.Line, issue.Location.Column = p.Line(), p.Column()
		}
		issues = append(issues, issue)
	}

	// YAML nodes retain source positions for reference errors.
	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		if len(issues) > 0 { return validationErrors{issues} }
		return err
	}
	if len(root.Content) > 0 { issues = append(issues, referenceErrors(file, root.Content[0])...) }
	if len(issues) > 0 { return validationErrors{issues} }
	return nil
}

func field(node *yamlv3.Node, key string) *yamlv3.Node {
	if node == nil || node.Kind != yamlv3.MappingNode { return nil }
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == key { return node.Content[i+1] }
	}
	return nil
}

func entries(node *yamlv3.Node) []*yamlv3.Node {
	if node != nil && node.Kind == yamlv3.SequenceNode { return node.Content }
	return nil
}

func value(node *yamlv3.Node) string {
	if node == nil { return "" }
	return node.Value
}

func referenceErrors(file string, root *yamlv3.Node) []error {
	var issues []error
	add := func(message string, node *yamlv3.Node) {
		issues = append(issues, Error{Message: message, Location: Location{File: file, Line: node.Line, Column: node.Column}})
	}
	ns := value(field(root, "namespace"))
	if ns == "" { ns = "default" }
	segments := map[string]bool{}
	for _, segment := range entries(field(root, "segments")) { segments[value(field(segment, "key"))] = true }
	for _, flag := range entries(field(root, "flags")) {
		key := value(field(flag, "key"))
		variants := map[string]bool{}
		for _, variant := range entries(field(flag, "variants")) { variants[value(field(variant, "key"))] = true }
		checkSegment := func(segment *yamlv3.Node, rule int) {
			if segment == nil { return }
			var keys []*yamlv3.Node
			if segment.Kind == yamlv3.ScalarNode { keys = append(keys, segment) } else {
				if k := field(segment, "key"); k != nil { keys = append(keys, k) }
				keys = append(keys, entries(field(segment, "keys"))...)
			}
			for _, k := range keys {
				if !segments[k.Value] { add(fmt.Sprintf("flag %s/%s rule %d references unknown segment %q", ns, key, rule, k.Value), k) }
			}
		}
		for i, rule := range entries(field(flag, "rules")) {
			checkSegment(field(rule, "segment"), i+1)
			for _, dist := range entries(field(rule, "distributions")) {
				v := field(dist, "variant")
				if v != nil && !variants[v.Value] { add(fmt.Sprintf("flag %s/%s rule %d references unknown variant %q", ns, key, i+1, v.Value), v) }
			}
		}
		for i, rollout := range entries(field(flag, "rollouts")) { checkSegment(field(rollout, "segment"), i+1) }
	}
	return issues
}
